<template><section class="module-view">
  <div class="tabs"><button v-for="item in ['Time course','Trait distribution','Associations','Donors','Source']" :aria-pressed="view===item" @click="view=item;loadView()">{{item}}</button></div>
  <div class="module-stage"><div class="controls"><label>Hormone <select v-model="hormone" @change="loadTime"><option value="ins">Insulin</option><option value="gcg">Glucagon</option></select></label><span>{{matrix.length ? donors.length + ' donors' : ''}}</span></div>
  <details v-if="view!=='Time course'" class="plot-settings"><summary>Filter donors</summary><div class="controls"><label>Filter donors <select v-model="field"><option value="">All donors</option><option v-for="key in filterFields" :key="key">{{key}}</option></select></label><input v-if="field" v-model="value" placeholder="Exact value or minimum…"/><select v-if="field" v-model="operator"><option value="equals">Equals</option><option value="min">At least</option><option value="max">At most</option></select></div></details><p v-if="error" role="alert">{{error}} <button @click="loadView">Retry</button></p><p v-if="busy" role="status">Loading selected assay…</p>
  <div v-if="view==='Time course' && points.length"><TimeSeriesLinePlot :key="hormone" :initial-content="content" :plot-data="points" :donors="donors" :metadata="metadata" :plot-id="'functional-'+hormone" :timepoints="timepoints" :y-axis-labels="units" @showContent="content=$event;loadTime()"/><details class="plot-settings"><summary>Filter donors</summary><div class="controls"><label>Filter donors <select v-model="field"><option value="">All donors</option><option v-for="key in filterFields" :key="key">{{key}}</option></select></label><input v-if="field" v-model="value" placeholder="Exact value or minimum…"/><select v-if="field" v-model="operator"><option value="equals">Equals</option><option value="min">At least</option><option value="max">At most</option></select></div></details><p class="source">Source functional_dataset_v1 · {{content?'Content-normalized':'IEQ-normalized'}} · Missing measurements remain missing. The confidence display retains the upstream browser's calculation.</p><button @click="downloadPoints">Download selected measurements</button></div>
  <div v-if="view==='Trait distribution'"><div class="controls"><label>Functional trait <select v-model="trait"><option v-for="key in traits" :key="key">{{key}}</option></select></label><label>Group by <select v-model="group"><option v-for="key in filterFields" :key="key">{{key}}</option></select></label></div><FunctionalViolinPlot v-if="traitRows.length" :data="traitRows" :x-field="group" :x-label="group" :y-field="trait" :y-label="trait"/><p v-else-if="!busy && !error">No recorded measurements match these filters.</p></div>
  <div v-if="view==='Associations'"><div class="controls"><label>Trait <select v-model="association" @change="loadAssociation"><option v-for="key in associationTraits" :key="key">{{key}}</option></select></label><label><input type="checkbox" v-model="skipped" @change="loadAssociation"/>Show source skipped analyses</label></div><p class="source">Source cohort association results are not recomputed when donor filters change.</p><div class="heatmap-scroll"><table v-if="associationRows.length"><thead><tr><th v-for="key in Object.keys(associationRows[0])">{{key}}</th></tr></thead><tbody><tr v-for="(row,i) in associationRows" :key="i"><td v-for="key in Object.keys(associationRows[0])">{{row[key]}}</td></tr></tbody></table></div></div>
  <div v-if="view==='Donors'" class="heatmap-scroll"><table><thead><tr><th>Accession</th><th v-for="key in filterFields">{{key}}</th></tr></thead><tbody><tr v-for="row in filteredMetadata" :key="row.Accession"><td>{{row.Accession}}</td><td v-for="key in filterFields">{{row[key]}}</td></tr></tbody></table></div>
  <div v-if="view==='Source'" class="source-panel"><h2>Source &amp; methods</h2><p>PanKbase dynamic perifusion data. Source normalization, hormone units, stimulus intervals and donor identities remain distinct. The graph record supplies related context; no matching cohort is assumed.</p><a href="https://pankbase.org/functional.html" target="_blank" rel="noopener">PanKbase functional methods and downloads ↗</a></div>
</div></section></template>
<script>
import { tsvParse, csvParse } from 'd3';
import { assetUrl } from './source.mjs';
import { readPublic } from './data.mjs';
import { downloadText } from './assets.mjs';
import TimeSeriesLinePlot from './vendor/functional/TimeSeriesLinePlot.vue';
import FunctionalViolinPlot from './vendor/functional/FunctionalViolinPlot.vue';
const base=assetUrl('functional/');
const number=value=>value==='-'||value===''||!Number.isFinite(Number(value))?'-':Number(value);
export default {components:{TimeSeriesLinePlot,FunctionalViolinPlot},props:['context'],data:()=>({hormone:'ins',content:false,view:'Time course',metadata:[],matrix:[],points:[],timepoints:[],allTraits:[],trait:'',group:'Gender',field:'',value:'',operator:'equals',error:'',busy:false,serial:0,association:'Age',skipped:false,associationRows:[],associationTraits:['Age','BMI','Derived-Diabetes-Status','Diabetes-status','Ethnicities','Gender','Genetic-sex','HbA1c']}),
  computed:{filterFields(){return ['Age (years)','Gender','Genetic sex','BMI','Ethnicities','HbA1C (percentage)','Description of diabetes status','Derived diabetes status','Isolation_center','Pre-Shipment Culture Time (hours)','C-Peptide (ng/ml)'].filter(k=>this.metadata.some(r=>r[k]!==undefined));},availableDonors(){return this.matrix.length?Object.keys(this.matrix[0]).filter(k=>!['time','timepoint'].includes(k)):[];},filteredMetadata(){return this.metadata.filter(r=>this.availableDonors.includes(r.Accession)&&(!this.field||!this.value||(this.operator==='equals'?String(r[this.field]).toLowerCase()===this.value.toLowerCase():Number.isFinite(Number(r[this.field]))&&(this.operator==='min'?Number(r[this.field])>=Number(this.value):Number(r[this.field])<=Number(this.value)))));},donors(){return this.field&&this.value?this.filteredMetadata.map(r=>r.Accession):this.availableDonors;},units(){const label=this.hormone==='ins'?'Insulin':'Glucagon';return {content:label+' secretion\n% content min',ieq:label+' secretion\n('+(this.hormone==='ins'?'ng':'pg')+'/100 IEQs/min)'};},traits(){return this.allTraits.length?Object.keys(this.allTraits[0]).filter(k=>!['Pankbase_ID','Donor ID'].includes(k)):[];},traitRows(){return this.allTraits.filter(r=>this.donors.includes(r.Pankbase_ID)&&Number.isFinite(Number(r[this.trait]))).map(r=>({...r,[this.trait]:Number(r[this.trait]),[this.group]:this.metadata.find(m=>m.Accession===r.Pankbase_ID)?.[this.group]||'Unknown'}));}},
  async mounted(){await this.loadView();},
  methods:{async loadTime(){const token=++this.serial;this.busy=true;this.error='';this.points=[];this.matrix=[];try{const [raw,timing]=await Promise.all([readPublic(base+`HIPP_${this.hormone}_${this.content?'content':'ieq'}.pankbase.txt`),readPublic(assetUrl(`functional/HIPP_${this.hormone}_ieq.timepoints.txt`))]);if(token!==this.serial)return;this.matrix=tsvParse(this.content?'timepoint\ttime\t'+raw:raw);this.timepoints=tsvParse(timing,row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k,v!==''&&Number.isFinite(Number(v))?Number(v):v])));this.points=this.availableDonors.flatMap(donor=>this.matrix.map(row=>({donor,time:Number(row.time),score:number(row[donor])})));}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},async loadView(){this.error='';this.busy=true;try{if(!this.metadata.length)this.metadata=tsvParse(await readPublic(base+'meta-data.merged.pankbase.combined.final.txt'));if(this.view==='Time course')return await this.loadTime();if(this.view==='Trait distribution'&&!this.allTraits.length){this.allTraits=tsvParse(await readPublic(base+'HIPP_all_traits.pankbase.txt'));this.trait=this.traits[0]||'';this.group=this.filterFields.includes('Gender')?'Gender':this.filterFields[0]||'';}if(this.view==='Associations')await this.loadAssociation();}catch(e){this.error=e.message;}finally{this.busy=false;}},async loadAssociation(){const token=++this.serial;this.associationRows=[];this.error='';this.busy=true;try{const rows=csvParse(await readPublic(base+'assoc_csv/HIPP_'+this.association+(this.skipped?'_skipped':'')+'.csv'));if(token===this.serial)this.associationRows=rows;}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},downloadPoints(){downloadText(['donor\ttime_minutes\tscore\tnormalization',...this.points.filter(p=>this.donors.includes(p.donor)).map(p=>[p.donor,p.time,p.score,this.content?'content':'IEQ'].join('\t'))].join('\n'),this.hormone+'-functional-measurements.tsv');}},
};
</script>
